package pe.financiera.prestamos;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.*;
import java.math.*;
import java.time.LocalDate;
import java.util.*;
import java.util.stream.Collectors;

record ClientInput(
 @NotBlank(message="Ingresa el DNI.") @Pattern(regexp="\\d{8}",message="El DNI debe contener exactamente 8 números, sin letras ni símbolos.") String dni,
 @NotBlank(message="Ingresa los nombres.") @Size(max=80,message="Los nombres no pueden superar 80 caracteres.") @Pattern(regexp="[\\p{L}]+(?:[ '\\-][\\p{L}]+)*",message="Usa letras, espacios, apóstrofes o guiones en los nombres.") String names,
 @NotBlank(message="Ingresa los apellidos.") @Size(max=80,message="Los apellidos no pueden superar 80 caracteres.") @Pattern(regexp="[\\p{L}]+(?:[ '\\-][\\p{L}]+)*",message="Usa letras, espacios, apóstrofes o guiones en los apellidos.") String surnames,
 @NotBlank(message="Ingresa un celular.") @Pattern(regexp="9\\d{8}",message="El celular debe tener 9 dígitos y comenzar con 9.") String phone,
 @NotBlank(message="Ingresa la dirección exacta declarada por el cliente.") @Size(max=200,message="La dirección no puede superar 200 caracteres.") String address,
 @NotBlank(message="Selecciona un departamento.") @Size(max=80) String department,
 @NotBlank(message="Selecciona una provincia.") @Size(max=80) String province,
 @NotBlank(message="Selecciona un distrito.") @Size(max=80) String district,
 @NotBlank(message="Selecciona una ubicación del catálogo UBIGEO.") @Pattern(regexp="[0-9]{6}",message="El UBIGEO debe contener seis dígitos.") String ubigeo,
 @Size(max=200) String addressReference,
 @NotBlank(message="Consulta el DNI antes de guardar.") String verificationId){}
record ClientAddressInput(
 @NotBlank(message="Selecciona un departamento.") @Size(max=80) String department,
 @NotBlank(message="Selecciona una provincia.") @Size(max=80) String province,
 @NotBlank(message="Selecciona un distrito.") @Size(max=80) String district,
 @NotBlank(message="Selecciona una ubicación del catálogo UBIGEO.") @Pattern(regexp="[0-9]{6}",message="El UBIGEO debe contener seis dígitos.") String ubigeo,
 @NotBlank(message="Ingresa la dirección exacta declarada por el cliente.") @Size(max=200,message="La dirección no puede superar 200 caracteres.") String address,
 @Size(max=200) String addressReference) {}
record DniLookupInput(@NotBlank(message="Ingresa el DNI.") @Pattern(regexp="\\d{8}",message="El DNI debe contener exactamente 8 números.") String dni){}
record LoanInput(@NotNull Long clientId,
 @NotBlank(message="Ingresa un monto.") @Size(max=5,message="El monto no puede superar S/ 10,000.") @Pattern(regexp="[0-9]+",message="El monto debe contener únicamente dígitos enteros.") String amount,
 @NotBlank(message="Ingresa el número de cuotas.") @Size(max=2,message="El número de cuotas debe estar entre 1 y 36.") @Pattern(regexp="[0-9]+",message="El número de cuotas debe contener únicamente dígitos enteros.") String installments) {
 BigDecimal amountValue(){return new BigDecimal(amount);}
 int installmentsValue(){return Integer.parseInt(installments);}
}
record ClientView(Long id,String dni,String names,String surnames,String phone,String address,String department,String province,String district,String ubigeo,String addressReference,LocalDate registeredAt,boolean active,String agency,Long agencyId){}
record AgencyView(Long id,String name,boolean enabled){}

@RestController @RequestMapping("/api")
class Api {
 private static final BigDecimal ZERO=BigDecimal.ZERO, LIMIT=new BigDecimal("10000.00"), TEA=new BigDecimal("0.30");
 private final ClientRepository clients;private final LoanRepository loans;private final InstallmentRepository installments;private final UserRepository users;private final AgencyRepository agencies;private final DniVerificationService dniVerification;private final UbigeoCatalog ubigeos;
 Api(ClientRepository c,LoanRepository l,InstallmentRepository i,UserRepository u,AgencyRepository a,DniVerificationService dniVerification,UbigeoCatalog ubigeos){clients=c;loans=l;installments=i;users=u;agencies=a;this.dniVerification=dniVerification;this.ubigeos=ubigeos;}
 AppUser actor(Authentication auth){return users.findByUsername(auth.getName()).orElseThrow();}
 boolean admin(AppUser u){return "ADMIN".equals(u.role);}
 List<Loan> scopedLoans(AppUser u){return admin(u)?loans.findAllByOrderByIdDesc():loans.findByAgencyIdOrderByIdDesc(u.agency.id);}
 Map<String,Object> profile(AppUser u){return Map.of("id",u.id,"username",u.username,"role",u.role,"agency",u.agency==null?"Todas las sedes":u.agency.name,"agencyId",u.agency==null?0:u.agency.id,"enabled",u.enabled);}
 @GetMapping("/me") Map<String,Object> me(Authentication a){return profile(actor(a));}
 @PostMapping("/clients/dni-lookup") ResponseEntity<?> lookupDni(@Valid @RequestBody DniLookupInput request,Authentication auth){
  try{return ResponseEntity.ok(dniVerification.lookup(request.dni(),actor(auth)));}
  catch(DniLookupException e){return ResponseEntity.status(e.status).body(Map.of("error",e.getMessage()));}
 }
 @GetMapping("/dashboard") Map<String,Object> dashboard(Authentication a){AppUser u=actor(a);List<Loan> ls=scopedLoans(u);Set<Long> ids=ls.stream().map(x->x.id).collect(Collectors.toSet());List<Installment> all=ids.isEmpty()?List.of():installments.findByLoanIdInOrderByDueDate(ids);LocalDate today=LocalDate.now();List<Installment> late=all.stream().filter(x->x.dueDate.isBefore(today)&&x.outstanding().signum()>0).toList();BigDecimal recovered=all.stream().map(x->x.principalPaid.add(x.interestPaid).add(x.insurancePaid)).reduce(ZERO,BigDecimal::add);BigDecimal overdueBalance=late.stream().map(Installment::outstanding).reduce(ZERO,BigDecimal::add);return Map.of("clients",admin(u)?clients.count():clients.countByAgency_Id(u.agency.id),"activeLoans",ls.stream().filter(x->"ACTIVO".equals(x.status)).count(),"totalLoans",ls.size(),"portfolio",ls.stream().filter(x->"ACTIVO".equals(x.status)).map(x->x.outstandingPrincipal).reduce(ZERO,BigDecimal::add),"recovered",recovered,"overdueBalance",overdueBalance,"overdueInstallments",(long)late.size(),"agency",u.agency==null?"Todas las sedes":u.agency.name);}
 @GetMapping("/dashboard/agencies") List<Map<String,Object>> agencyDashboard(Authentication a){AppUser user=actor(a);if(!admin(user))throw new org.springframework.security.access.AccessDeniedException("Solo el administrador puede consultar el consolidado de agencias.");return agencies.findAll().stream().map(agency->{List<Loan> ls=loans.findByAgencyIdOrderByIdDesc(agency.id);Set<Long> ids=ls.stream().map(l->l.id).collect(Collectors.toSet());List<Installment> rows=ids.isEmpty()?List.of():installments.findByLoanIdInOrderByDueDate(ids);List<Installment> late=rows.stream().filter(i->i.dueDate.isBefore(LocalDate.now())&&i.outstanding().signum()>0).toList();long overdue=late.size();BigDecimal recovered=rows.stream().map(i->i.principalPaid.add(i.interestPaid).add(i.insurancePaid)).reduce(ZERO,BigDecimal::add);BigDecimal overdueBalance=late.stream().map(Installment::outstanding).reduce(ZERO,BigDecimal::add);return Map.<String,Object>of("id",agency.id,"name",agency.name,"enabled",agency.enabled,"clients",clients.countByAgency_Id(agency.id),"activeLoans",ls.stream().filter(l->"ACTIVO".equals(l.status)).count(),"totalLoans",ls.size(),"portfolio",ls.stream().filter(l->"ACTIVO".equals(l.status)).map(l->l.outstandingPrincipal).reduce(ZERO,BigDecimal::add),"recovered",recovered,"overdueBalance",overdueBalance,"overdueInstallments",overdue);}).toList();}
  ClientView clientView(Client c){Agency agency=c.agency;return new ClientView(c.id,c.dni,c.names,c.surnames,c.phone,c.address,c.department,c.province,c.district,c.ubigeo,c.addressReference,c.registeredAt,c.active,agency==null?"":agency.getName(),agency==null?null:agency.getId());}
 @GetMapping("/locations/ubigeos") List<UbigeoEntry> ubigeoCatalog(Authentication auth){actor(auth);return ubigeos.entries();}
  Client visibleClient(Long id,AppUser user){if(admin(user))return clients.findById(id).orElseThrow(()->new IllegalArgumentException("Cliente no encontrado."));if(user.agency==null)throw new org.springframework.security.access.AccessDeniedException("La cuenta no tiene una sede asignada.");return clients.findByIdAndAgency_Id(id,user.agency.id).orElseThrow(()->new org.springframework.security.access.AccessDeniedException("Este cliente pertenece a otra sede o ya no está disponible en tu cartera."));}
  @GetMapping("/clients") @Transactional(readOnly=true) List<ClientView> searchClients(@RequestParam(defaultValue="") String q,@RequestParam(required=false) Long agencyId,Authentication auth){if(!q.isBlank()&&!q.matches("(?U)(?:[\\p{L}\\p{M} ]+|[0-9]+)"))throw new IllegalArgumentException("La búsqueda solo admite un nombre o un DNI.");AppUser user=actor(auth);if(!admin(user)&&agencyId!=null&&(user.agency==null||!agencyId.equals(user.agency.id)))throw new org.springframework.security.access.AccessDeniedException("No puedes consultar otra sede");List<Client> result;if(admin(user)){result=agencyId==null?clients.findAll():clients.findAllByAgency_IdOrderByIdDesc(agencyId);if(!q.isBlank()){String term=q.toLowerCase(Locale.ROOT);result=result.stream().filter(c->(c.dni+" "+c.names+" "+c.surnames).toLowerCase(Locale.ROOT).contains(term)).toList();}}else result=q.isBlank()?clients.findAllByAgency_IdOrderByIdDesc(user.agency.id):clients.searchForAgency(user.agency.id,q);return result.stream().map(this::clientView).toList();}
 @GetMapping("/clients/without-active-loans") @Transactional(readOnly=true) List<ClientView> clientsWithoutActiveLoans(@RequestParam(required=false) Long agencyId,Authentication auth){AppUser user=actor(auth);List<Client> result;if(admin(user)){result=agencyId==null?clients.findClientsWithoutActiveLoans():clients.findClientsWithoutActiveLoansByAgency(agencyId);}else{if(user.agency==null)throw new org.springframework.security.access.AccessDeniedException("La cuenta no tiene una sede asignada.");if(agencyId!=null&&!agencyId.equals(user.agency.id))throw new org.springframework.security.access.AccessDeniedException("No puedes consultar otra sede");result=clients.findClientsWithoutActiveLoansByAgency(user.agency.id);}return result.stream().map(this::clientView).toList();}
 @GetMapping("/clients/credit-summary") @Transactional(readOnly=true) List<Map<String,Object>> clientCreditSummary(Authentication auth){AppUser user=actor(auth);List<Client> visible=admin(user)?clients.findAll():clients.findAllByAgency_IdOrderByIdDesc(user.agency.id);LocalDate today=LocalDate.now();return visible.stream().map(c->{List<Loan> records=admin(user)?loans.findByClientIdOrderByIdDesc(c.id):loans.findByClientAndAgency(c.id,user.agency.id);List<Loan> active=records.stream().filter(l->"ACTIVO".equals(l.status)).toList();Set<Long> ids=active.stream().map(l->l.id).collect(Collectors.toSet());List<Installment> due=ids.isEmpty()?List.of():installments.findByLoanIdInOrderByDueDate(ids);long overdue=due.stream().filter(i->i.dueDate.isBefore(today)&&i.outstanding().signum()>0).count();BigDecimal balance=active.stream().map(l->l.outstandingPrincipal).reduce(ZERO,BigDecimal::add);String status=overdue>0?"MOROSO":active.isEmpty()?"SIN_CREDITOS":"AL_DIA";return Map.<String,Object>of("clientId",c.id,"dni",c.dni,"loans",records.size(),"activeLoans",active.size(),"outstandingPrincipal",balance,"overdueInstallments",overdue,"creditStatus",status);}).toList();}
 @GetMapping("/clients/by-dni") @Transactional(readOnly=true) ResponseEntity<?> lookupClientByDni(@RequestParam String dni,Authentication auth){if(!dni.matches("\\d{8}"))throw new IllegalArgumentException("Escribe un DNI de 8 números para buscar.");AppUser user=actor(auth);Optional<Client> found=admin(user)?clients.findAll().stream().filter(c->c.dni.equals(dni)).findFirst():clients.findForAgency(user.agency.id,dni);return found.<ResponseEntity<?>>map(c->ResponseEntity.ok(clientView(c))).orElseGet(()->ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of("error","No hay un cliente con ese DNI en tu sede. Puedes registrarlo aquí si pertenece a esta cartera.")));}
 @PostMapping("/clients") @Transactional ClientView createClient(@Valid @RequestBody ClientInput x,Authentication auth){AppUser user=actor(auth);if(user.agency==null||!"ADVISOR".equals(user.role))throw new IllegalArgumentException("Registra cada cliente desde la cuenta de asesor de su sede.");if(clients.existsByDni(x.dni()))throw new DniLookupException(409,"Este DNI ya se encuentra registrado en el sistema.");UbigeoEntry official=validateLocation(x.department(),x.province(),x.district(),x.ubigeo());VerifiedIdentity identity=dniVerification.consume(x.verificationId(),x.dni(),user);if(!identity.names().equals(x.names().trim())||!identity.surnames().equals(x.surnames().trim()))throw new DniLookupException(400,"Los nombres deben coincidir con la consulta validada. Vuelve a consultar el DNI.");Client c=new Client();c.agency=user.agency;c.dni=identity.dni();c.names=identity.names();c.surnames=identity.surnames();c.phone=x.phone();c.address=x.address().trim();c.department=official.department();c.province=official.province();c.district=official.district();c.ubigeo=official.ubigeo();c.addressReference=blankToNull(x.addressReference());return clientView(clients.saveAndFlush(c));}
 @PutMapping("/clients/{id}/address") @Transactional ClientView updateClientAddress(@PathVariable Long id,@Valid @RequestBody ClientAddressInput input,Authentication auth){AppUser user=actor(auth);if(!"ADVISOR".equals(user.role))throw new org.springframework.security.access.AccessDeniedException("Solo el asesor asignado puede actualizar el domicilio del cliente.");Client client=visibleClient(id,user);UbigeoEntry official=validateLocation(input.department(),input.province(),input.district(),input.ubigeo());client.department=official.department();client.province=official.province();client.district=official.district();client.ubigeo=official.ubigeo();client.address=input.address().trim();client.addressReference=blankToNull(input.addressReference());return clientView(clients.saveAndFlush(client));}
 UbigeoEntry validateLocation(String department,String province,String district,String code){UbigeoEntry official=ubigeos.find(code).orElseThrow(()->new IllegalArgumentException("El UBIGEO no existe en el catálogo del INEI."));if(!ubigeos.same(official.department(),department)||!ubigeos.same(official.province(),province)||!ubigeos.same(official.district(),district))throw new IllegalArgumentException("Departamento, provincia, distrito y UBIGEO deben coincidir con el catálogo oficial.");return official;}
 String blankToNull(String value){return value==null||value.isBlank()?null:value.trim();}
 String normalizePhone(String value){if(value==null||value.isBlank())return null;String digits=value.replaceAll("\\D","");return digits.length()==11&&digits.startsWith("51")?digits.substring(2):digits;}
  @GetMapping("/clients/{id}") @Transactional(readOnly=true) ClientView clientDetail(@PathVariable Long id,Authentication auth){return clientView(visibleClient(id,actor(auth)));}
  @GetMapping("/clients/{id}/loans") @Transactional(readOnly=true) List<Map<String,Object>> clientLoans(@PathVariable Long id,Authentication auth){AppUser user=actor(auth);Client c=visibleClient(id,user);List<Loan> result=admin(user)?loans.findByClientIdOrderByIdDesc(id):loans.findByClientAndAgency(id,user.agency.id);return result.stream().map(this::loanView).toList();}
 @GetMapping("/loans") List<Map<String,Object>> listLoans(@RequestParam(required=false) Long agencyId,Authentication a){AppUser user=actor(a);if(!admin(user)&&agencyId!=null&&(user.agency==null||!agencyId.equals(user.agency.id)))throw new org.springframework.security.access.AccessDeniedException("No puedes consultar otra agencia");List<Loan> result=admin(user)?(agencyId==null?loans.findAllByOrderByIdDesc():loans.findByAgencyIdOrderByIdDesc(agencyId)):scopedLoans(user);return result.stream().map(this::loanView).toList();}
 Map<String,Object> loanView(Loan l){BigDecimal totalOutstanding=installments.findByLoanIdOrderByNumber(l.id).stream().map(Installment::outstanding).reduce(ZERO,BigDecimal::add);Map<String,Object> view=new LinkedHashMap<>();view.put("id",l.id);view.put("clientId",l.client.id);view.put("client",l.client.names+" "+l.client.surnames);view.put("dni",l.client.dni);view.put("agency",l.agency.getName());view.put("agencyId",l.agency.getId());view.put("principal",l.principal);view.put("outstandingPrincipal",l.outstandingPrincipal);view.put("totalOutstanding",totalOutstanding);if(l.annualRate!=null)view.put("annualRate",l.annualRate);view.put("installments",l.installments);view.put("disbursedAt",l.disbursedAt);view.put("status",l.status);return view;}
  void validateLoanInput(LoanInput input){BigDecimal amount=input.amountValue();int count=input.installmentsValue();if(amount.signum()<=0||amount.compareTo(LIMIT)>0)throw new IllegalArgumentException("El monto debe ser un entero entre S/ 1 y S/ 10,000.");if(count<1||count>36)throw new IllegalArgumentException("El número de cuotas debe ser un entero entre 1 y 36.");}
  @PostMapping("/loans/evaluation") @Transactional(readOnly=true) Map<String,Object> evaluateLoan(@Valid @RequestBody LoanInput x,Authentication auth){validateLoanInput(x);BigDecimal amount=x.amountValue();int count=x.installmentsValue();AppUser user=actor(auth);if(user.agency==null||!user.agency.enabled)throw new IllegalArgumentException("La cuenta no tiene una sede habilitada");Client c=clients.findById(x.clientId()).orElseThrow(()->new IllegalArgumentException("Cliente no encontrado"));
  // Se reutiliza el cliente nacional y la sede del asesor autenticado.
  if(!c.active)throw new IllegalArgumentException("El cliente está inactivo");BigDecimal original=loans.pendingOriginalCapitalByDni(c.dni),available=LIMIT.subtract(original).max(ZERO);if(overdue(c.dni))throw new IllegalArgumentException("Cliente con cuotas vencidas: debe regularizar su situación");if(original.add(amount).compareTo(LIMIT)>0)throw new IllegalArgumentException("El capital original activo global excedería S/ 10,000. Disponible: S/ "+available);BigDecimal monthly=BigDecimal.valueOf(Math.pow(BigDecimal.ONE.add(TEA).doubleValue(),30.0/360.0)-1).setScale(12,RoundingMode.HALF_UP);MathContext mc=new MathContext(18,RoundingMode.HALF_UP);BigDecimal factor=BigDecimal.ONE.add(monthly).pow(count,mc);BigDecimal pay=amount.multiply(monthly).divide(BigDecimal.ONE.subtract(BigDecimal.ONE.divide(factor,mc)),2,RoundingMode.HALF_UP);return Map.of("client",c.names+" "+c.surnames,"dni",c.dni,"agency",user.agency.name,"principal",amount.setScale(2,RoundingMode.HALF_UP),"installments",count,"monthlyPaymentEstimate",pay,"totalPaymentEstimate",pay.multiply(BigDecimal.valueOf(count)).setScale(2,RoundingMode.HALF_UP),"availableOriginalCapital",available,"annualRate",TEA);}
  @PostMapping("/loans") @Transactional Map<String,Object> createLoan(@Valid @RequestBody LoanInput x,Authentication auth){validateLoanInput(x);BigDecimal amount=x.amountValue();int count=x.installmentsValue();AppUser user=actor(auth);if(user.agency==null||!user.agency.enabled)throw new IllegalArgumentException("La cuenta no tiene una sede habilitada");Client c=clients.findByIdForUpdate(x.clientId()).orElseThrow(()->new IllegalArgumentException("Cliente no encontrado"));
  // Se reutiliza el cliente nacional y la sede del asesor autenticado.
  if(!c.active)throw new IllegalArgumentException("El cliente está inactivo");BigDecimal outstanding=loans.pendingOriginalCapitalByDni(c.dni);if(overdue(c.dni))throw new IllegalArgumentException("Cliente con cuotas vencidas: debe regularizar su situación");if(outstanding.add(amount).compareTo(LIMIT)>0)throw new IllegalArgumentException("El capital original activo global excedería S/ 10,000. Disponible: S/ "+LIMIT.subtract(outstanding));
  Loan l=new Loan();l.client=c;l.agency=user.agency;l.createdBy=user;l.principal=amount.setScale(2,RoundingMode.HALF_UP);l.outstandingPrincipal=l.principal;l.installments=count;l.insurance=false;l.disbursedAt=LocalDate.now();loans.saveAndFlush(l);generateSchedule(l);return loanView(l);}
 void generateSchedule(Loan l){BigDecimal monthly=BigDecimal.valueOf(Math.pow(1.30,30.0/360.0)-1).setScale(12,RoundingMode.HALF_UP);MathContext mc=new MathContext(18,RoundingMode.HALF_UP);BigDecimal factor=BigDecimal.ONE.add(monthly).pow(l.installments,mc);BigDecimal annuityDenominator=BigDecimal.ONE.subtract(BigDecimal.ONE.divide(factor,mc));BigDecimal pay=l.principal.multiply(monthly).divide(annuityDenominator,2,RoundingMode.HALF_UP);BigDecimal balance=l.principal;for(int n=1;n<=l.installments;n++){BigDecimal interest=balance.multiply(monthly).setScale(2,RoundingMode.HALF_UP);BigDecimal principal=n==l.installments?balance:pay.subtract(interest).max(ZERO).min(balance);BigDecimal insurance=l.insurance?balance.multiply(new BigDecimal("0.0005")).setScale(2,RoundingMode.HALF_UP):ZERO;Installment i=new Installment();i.loan=l;i.number=n;i.dueDate=l.disbursedAt.plusDays(30L*n);i.principalDue=principal;i.interestDue=interest;i.insuranceDue=insurance;installments.save(i);balance=balance.subtract(principal);}}
 boolean overdue(String dni){return loans.findByClientDniAndStatus(dni,"ACTIVO").stream().flatMap(l->installments.findByLoanIdOrderByNumber(l.id).stream()).anyMatch(i->i.dueDate.isBefore(LocalDate.now())&&i.outstanding().signum()>0);}
 @GetMapping("/loans/{id}/schedule") List<Map<String,Object>> schedule(@PathVariable Long id,Authentication auth){Loan l=visibleLoan(id,actor(auth));return installments.findByLoanIdOrderByNumber(l.id).stream().map(i->Map.<String,Object>of("id",i.id,"number",i.number,"dueDate",i.dueDate,"principal",i.principalDue,"interest",i.interestDue,"paid",i.principalPaid.add(i.interestPaid).add(i.insurancePaid),"outstanding",i.outstanding(),"status",i.status)).toList();}
 Loan visibleLoan(Long id,AppUser user){Loan l=loans.findById(id).orElseThrow(()->new IllegalArgumentException("Préstamo no encontrado"));if(!admin(user)&&!l.agency.id.equals(user.agency.id))throw new org.springframework.security.access.AccessDeniedException("Este préstamo pertenece a otra sede");return l;}
 @GetMapping("/admin/agencies") List<AgencyView> agencies(){return agencies.findAll().stream().map(a->new AgencyView(a.id,a.name,a.enabled)).toList();}
 @GetMapping("/admin/users") List<Map<String,Object>> userList(){return users.findAll().stream().map(this::profile).toList();}
 @PostMapping("/admin/users") ResponseEntity<Map<String,String>> createUserDisabled(){throw new org.springframework.security.access.AccessDeniedException("La creación de cuentas está deshabilitada; se conservan las cuentas asignadas al proyecto.");}
 @ExceptionHandler({IllegalArgumentException.class,org.springframework.security.access.AccessDeniedException.class,DniLookupException.class}) ResponseEntity<Map<String,String>> businessError(RuntimeException e){HttpStatus status=e instanceof DniLookupException d?HttpStatus.valueOf(d.status):e instanceof org.springframework.security.access.AccessDeniedException?HttpStatus.FORBIDDEN:HttpStatus.BAD_REQUEST;return ResponseEntity.status(status).body(Map.of("error",e.getMessage()));}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> invalidFields(MethodArgumentNotValidException e){Map<String,String> fields=new LinkedHashMap<>();for(FieldError error:e.getBindingResult().getFieldErrors())fields.putIfAbsent(error.getField(),error.getDefaultMessage());return ResponseEntity.badRequest().body(Map.of("error","Revisa los campos marcados antes de guardar.","fieldErrors",fields));}
 @ExceptionHandler(HttpMessageNotReadableException.class) ResponseEntity<Map<String,String>> unreadableRequest(){return ResponseEntity.badRequest().body(Map.of("error","No se pudieron leer los datos enviados. Revisa el formato de cada campo e inténtalo de nuevo."));}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<Map<String,String>> duplicateData(){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","No se guardó: el DNI ya existe o hay un dato que entra en conflicto con el registro."));}
}
